145	UlyssesGroup::UlyssesGroup(std::string group_name, int64_t rank, int64_t world_size, int64_t device_index):
146	    group_name_(std::move(group_name)),
147	    rank_(static_cast<int>(rank)),
148	    world_size_(static_cast<int>(world_size)),
149	    device_index_(static_cast<int>(device_index))
150	{
151	    TORCH_CHECK(world_size_ >= 1 && world_size_ <= 8,
152	                "world_size must be in [1, 8] -- fast-ulysses is single-node -- got ",
153	                world_size_);
154	    TORCH_CHECK(rank_ >= 0 && rank_ < world_size_, "rank ", rank_, " out of range for world_size ", world_size_);
155	}
156	
157	UlyssesGroup::~UlyssesGroup()
158	{
159	    destroy();
160	}
161	
162	void UlyssesGroup::check_alive() const
163	{
164	    TORCH_CHECK(!destroyed_, "this UlyssesGroup has been destroyed");
165	}
166	
167	const A2APlan& UlyssesGroup::plan(at::IntArrayRef                            sizes,
168	                                  int64_t                                    mode,
169	                                  at::ScalarType                             dtype,
170	                                  const std::optional<std::vector<int64_t>>& seq_splits,
171	                                  const std::optional<std::vector<int64_t>>& head_splits)
172	{
173	    PlanKey key;
174	    key.sizes = sizes.vec();
175	    key.mode  = mode;
176	    key.dtype = dtype;
177	    // Kept optional, so "no splits" and "empty splits" are distinct keys. Collapsing them would
178	    // let an even-split call warm the cache for a later empty-split one, which make_dims rejects.
179	    key.seq  = seq_splits;
180	    key.head = head_splits;
181	
182	    auto it = plans_.find(key);
183	    if (it != plans_.end()) {
184	        return it->second;
185	    }
186	    // A caller whose shapes are data-dependent would otherwise grow this without bound. Dropping
187	    // everything costs one rebuild per live shape, which is microseconds.
188	    if (plans_.size() >= 512) {
189	        plans_.clear();
190	    }
191	    const A2ADims dims = make_dims(sizes, dtype, mode, world_size_, rank_, seq_splits, head_splits);
192	    return plans_
193	        .emplace(std::move(key),
194	                 build_plan(dims, static_cast<int>(mode), static_cast<int64_t>(c10::elementSize(dtype))))
195	        .first->second;
196	}
197	
198	void UlyssesGroup::prune_owned()
199	{
200	    // The caller's buffer is a view over the window's storage, so a use count of one means we are
201	    // the only holder left and the allocation can go back to the symmetric allocator.
202	    for (auto it = owned_.begin(); it != owned_.end();) {
203	        it = (it->second.tensor.storage().use_count() == 1) ? owned_.erase(it) : std::next(it);
204	    }
205	}
206	
207	Window UlyssesGroup::allocate(int64_t numel, at::ScalarType dtype)
208	{
209	    // Every rank computes the same window size (it is the max over all ranks), so this throws on
210	    // all of them together and cannot leave anyone waiting. A zero-sized symmetric allocation has
211	    // a null data_ptr, which rendezvous refuses with a null handle.
212	    TORCH_CHECK(numel > 0,
213	                "this call moves no data: every rank's shard is empty. Check the shape and the "
214	                "splits -- a sequence or head axis of 0 on ALL ranks has nothing to exchange");
215	    const at::cuda::CUDAGuard guard(device_index_);
216	    // empty_strided_p2p rather than a MemPool: it is the allocator entry point directly, so no
217	    // unrelated allocation can interleave with ours and desync the rendezvous order across ranks.
218	    at::Tensor t = symm::empty_strided_p2p(
219	        {numel}, {1}, dtype, c10::Device(c10::DeviceType::CUDA, device_index_), group_name_, std::nullopt);
220	    auto sym = symm::rendezvous(t, group_name_);
221	    TORCH_CHECK(sym,
222	                "torch symmetric memory did not establish a rendezvous for a ",
223	                numel,
224	                "-element window on group '",
225	                group_name_,
226	                "'. The allocation is not a symmetric one, or the group is not registered with "
227	                "torch's symmetric-memory bootstrap.");
228	
229	    Window win;
230	    win.tensor = t;
231	    win.numel  = numel;
232	    for (void* p : sym->get_buffer_ptrs()) {
233	        win.peer_ptrs.push_back(reinterpret_cast<uint64_t>(p));
234	    }
235	    const int64_t off = flag_offset_slots(world_size_);
236	    for (void* p : sym->get_signal_pad_ptrs()) {
237	        win.flag_ptrs.push_back(reinterpret_cast<uint64_t>(p) + static_cast<uint64_t>(off * 8));
238	    }
239	    TORCH_CHECK(static_cast<int>(win.peer_ptrs.size()) == world_size_,
240	                "rendezvous returned ",
241	                win.peer_ptrs.size(),
242	                " peers for a group of ",
243	                world_size_,
244	                "; the process group and this group disagree about their membership");
245	
246	    // This allocation may be reusing memory an earlier window freed, and the epoch has to start at
247	    // zero. Clear only our own region -- torch's channels are its business -- then hold every rank
248	    // until all have cleared, or one rank's first publish lands in a pad another has yet to clear,
249	    // is erased, and that rank waits forever for a write that already happened.
250	    sym->get_signal_pad(rank_, {flag_slots(world_size_)}, at::kLong, off).zero_();
251	    sym->barrier(0, 0);
252	    return win;
253	}
254	
255	const Window& UlyssesGroup::window(WindowRole role, at::ScalarType dtype, int64_t numel)
256	{
257	    check_alive();
258	    const auto key = std::make_pair(static_cast<int64_t>(role), dtype);
259	    auto       it  = windows_.find(key);
260	    if (it != windows_.end() && it->second.numel >= numel) {
261	        return it->second;
262	    }
263	    if (it != windows_.end()) {
264	        windows_.erase(it);  // free before allocating, so the allocator can reuse the segment
265	    }
266	    return windows_.emplace(key, allocate(numel, dtype)).first->second;
267	}
268	
269	const Window& UlyssesGroup::lend_window(at::ScalarType dtype, int64_t numel)
270	{
271	    check_alive();
272	    LentPool& pool = lent_[dtype];
273	    // The reference this returns outlives the call's own frame, so growth must not move the slots.
274	    // A no-op once the capacity is there, which is after the first kLentSlots calls.
275	    pool.slots.reserve(kLentSlots);
276	
277	    // The counter, never a search for a free slot: see the header for why the choice has to be a
278	    // quantity every rank shares. The pool fills before it rotates, so this branch runs exactly
279	    // kLentSlots times per dtype, at the same calls on every rank.
280	    const size_t idx = pool.calls++ % kLentSlots;
281	    if (idx == pool.slots.size()) {
282	        pool.slots.push_back(allocate(numel, dtype));
283	        return pool.slots.back();
284	    }
285	
286	    Window& slot = pool.slots[idx];
287	    // The rotation says WHICH slot; the reference count says whether the caller is done with it.
288	    // One holder means this pool is the only one left, the same test prune_owned() uses on owned_.
289	    TORCH_CHECK(slot.tensor.storage().use_count() == 1,
290	                "all_to_all_4d_async(lend=True) has rotated back to a window a live result still "
291	                "refers to: at most ",
292	                kLentSlots,
293	                " lent results may be alive at once. Drop the older ones before issuing more "
294	                "calls, or pass out= and own the buffer. Every rank has to drop them at the same "
295	                "point in its own program -- a lent window is symmetric memory, and the rotation "
296	                "is what keeps every rank on the same one.");
297	    if (slot.numel < numel) {
298	        slot = Window{};                // free before allocating, so the allocator can reuse the
299	        slot = allocate(numel, dtype);  // segment -- the order window() takes, for the same reason
300	    }
301	    return slot;
302	}
303	
304	at::Tensor UlyssesGroup::make_output(at::IntArrayRef shape, at::ScalarType dtype, int64_t numel)
305	{
306	    check_alive();
307	    prune_owned();  // before allocating, so a released buffer's memory can be reused right here
308	    Window     win = allocate(numel, dtype);
309	    at::Tensor out = win.tensor.narrow(0, 0, c10::multiply_integers(shape)).view(shape);
310	    owned_.emplace(win.tensor.data_ptr(), std::move(win));
311	    return out;
312	}
313	
314	const Window* UlyssesGroup::window_of(const at::Tensor& out) const
315	{
316	    auto it = owned_.find(out.data_ptr());
317	    return it == owned_.end() ? nullptr : &it->second;
318	}
319	
320	UlyssesGroup::Staging* UlyssesGroup::stage(const at::Tensor& x, c10::cuda::CUDAStream caller, cudaStream_t comm)
321	{
322	    auto key = std::make_pair(x.sizes().vec(), x.scalar_type());
323	    // Unlike plans_, every entry here pins up to kMaxStagingPerShape inputs' worth of device
324	    // memory, so the bound matters more -- 16 shapes is 16 * kMaxStagingPerShape buffers. Dropping
325	    // them all costs one extra copy per live shape on the next call, and release_staging() has
326	    // already been called for every slot by the time we get here.
327	    if (staging_.size() >= 16 && staging_.find(key) == staging_.end()) {
328	        for (auto& entry : staging_) {
329	            for (auto& slot : entry.second) {
330	                if (slot->release != nullptr) {
331	                    ULYSSES_CUDA_CHECK(cudaEventSynchronize(slot->release));
332	                    ULYSSES_CUDA_CHECK(cudaEventDestroy(slot->release));
333	                }
334	            }
335	        }
336	        staging_.clear();
337	    }
338	    auto& pool = staging_[key];
339	
340	    // Everything below happens on the CALLER's stream, so the caller's tensor is only ever read
341	    // there and the comm stream sees only the staged copy.
342	    const c10::cuda::CUDAStreamGuard guard(caller);
343	
344	    // Prefer a slot the comm stream has finished with: reusing it costs nothing, while a fresh one
345	    // costs an allocation. cudaEventQuery on a never-recorded event reports success, which is the
346	    // right answer for a slot that has never been read.
347	    Staging* slot = nullptr;
348	    for (auto& candidate : pool) {
349	        const cudaError_t status = cudaEventQuery(candidate->release);
350	        if (status == cudaSuccess) {
351	            slot = candidate.get();
352	            break;
353	        }
354	        if (status != cudaErrorNotReady) {
355	            ULYSSES_CUDA_CHECK(status);
356	        }
357	        // cudaErrorNotReady is this call's answer, not a failure -- but it still lands in the
358	        // sticky last error, where the next unrelated cudaGetLastError() would report it as its
359	        // own. Cleared here for the same reason at::cuda::CUDAEvent::query() clears it.
360	        (void)cudaGetLastError();
361	    }
362	
363	    if (slot == nullptr && pool.size() < kMaxStagingPerShape) {
364	        // Built into locals and committed together, so a throw from either leaves the pool
365	        // untouched and the next call retries. A half-built slot -- tensor defined, release still
366	        // null -- would be handed out and then throw on the null event, for good.
367	        //
368	        // at::empty, not empty_like: empty_like would copy a strided input's layout, and the
369	        // transport reads the staged buffer as dense.
370	        //
371	        // InferenceMode(false) around it: this buffer outlives the call that created it, and one
372	        // allocated under inference mode is an inference tensor for good -- every later copy_ into
373	        // it from outside inference mode raises, so a single call made there would retire that
374	        // (shape, dtype) permanently.
375	        const c10::InferenceMode no_inference(false);
376	        auto                     fresh   = std::make_unique<Staging>();
377	        at::Tensor               staged  = at::empty(x.sizes(), x.options());
378	        cudaEvent_t              release = nullptr;
379	        ULYSSES_CUDA_CHECK(cudaEventCreateWithFlags(&release, cudaEventDisableTiming));
380	        fresh->tensor  = std::move(staged);
381	        fresh->release = release;
382	        pool.push_back(std::move(fresh));
383	        slot = pool.back().get();
384	    }
385	    else if (slot == nullptr) {
386	        // Every slot is still in flight and the pool is at its bound, so this call waits for one.
387	        // pool.front() is the first slot BUILT, not the first that will retire -- the scan above
388	        // starts there, so it tends to be the most recently reused. Any in-flight slot is a
389	        // correct answer; a shorter wait would cost keeping the pool in retirement order, on a
390	        // path a caller reaches only by exceeding the bound.
391	        slot = pool.front().get();
392	        ULYSSES_CUDA_CHECK(cudaStreamWaitEvent(caller, slot->release, 0));
393	    }
394	
395	    slot->tensor.copy_(x);
396	    // The comm stream must not read the staged copy before that copy has run, and the ready event
397	    // trails everything already submitted on the caller's stream -- including any earlier consumer
398	    // of this same buffer.
399	    const Event ready(cudaEventDisableTiming);
400	    ULYSSES_CUDA_CHECK(cudaEventRecord(ready, caller));
401	    ULYSSES_CUDA_CHECK(cudaStreamWaitEvent(comm, ready, 0));
402	
403	    return slot;
404	}
405	
406	void UlyssesGroup::release_staging(Staging* slot, cudaStream_t comm) noexcept
407	{
408	    if (slot != nullptr) {
409	        // The slot is named by the caller rather than remembered here, because several calls can
410	        // be in flight at once and each must release the one it actually used.
411	        //
412	        // See the header: unchecked because this also runs while an exception from the transfer is
413	        // propagating, and because a checked record that failed would leave the same state.
414	        cudaEventRecord(slot->release, comm);
415	    }
416	}
417	
418	int64_t UlyssesGroup::staging_slots(const at::Tensor& like) const
419	{
420	    const auto it = staging_.find(std::make_pair(like.sizes().vec(), like.scalar_type()));
421	    return it == staging_.end() ? 0 : static_cast<int64_t>(it->second.size());
422	}
423	
424	int64_t UlyssesGroup::epoch(const at::Tensor& probe, WindowRole role) const
425	{
426	    // A buffer from empty_output() is its OWN window and lives in owned_, not in windows_ -- the
427	    // zero-copy path never touches the role windows at all. Look there first, so a caller that
428	    // passes the tensor it handed to `out=` gets that window's epoch rather than -1.
429	    const Window* win = window_of(probe);
430	    if (win == nullptr) {
431	        auto it = windows_.find(std::make_pair(static_cast<int64_t>(role), probe.scalar_type()));
432	        if (it == windows_.end()) {
433	            return -1;
434	        }
435	        win = &it->second;
436	    }
437	    // The epoch sits one slot past the ws flags, which is where barrier_kernel's atomicAdd lands.
438	    const auto         addr  = win->flag_ptrs[rank_] + static_cast<uint64_t>(world_size_) * 8;
439	    unsigned long long value = 0;
440	    ULYSSES_CUDA_CHECK(cudaMemcpy(&value, reinterpret_cast<const void*>(addr), sizeof(value), cudaMemcpyDeviceToHost));
441	    return static_cast<int64_t>(value);
442	}
443	
444	cudaStream_t UlyssesGroup::xfer_stream()
445	{
446	    if (xfer_ == nullptr) {
447	        const at::cuda::CUDAGuard guard(device_index_);
448	        ULYSSES_CUDA_CHECK(cudaStreamCreateWithFlags(&xfer_, cudaStreamNonBlocking));
449	    }
450	    return xfer_;
451	}
452	
453	void UlyssesGroup::destroy()
454	{
455	    if (destroyed_) {
456	        return;
457	    }
458	    destroyed_ = true;
459	    if (xfer_ != nullptr) {
460	        // Unchecked, like the rest of teardown: the caller has already quiesced the group, and a
461	        // throw from here would run during interpreter shutdown.
462	        cudaStreamSynchronize(xfer_);
463	        cudaStreamDestroy(xfer_);
464	        xfer_ = nullptr;
465	    }
466	    for (auto& entry : staging_) {
467	        for (auto& slot : entry.second) {
468	            if (slot->release != nullptr) {
469	                cudaEventDestroy(slot->release);
470	            }
471	        }
472	    }
473	    staging_.clear();
474	    plans_.clear();
475	    windows_.clear();
476	    // Lent windows behave like owned ones here, and like them a result the caller still holds stays
477	    // alive through its own storage reference; dropping the pools releases only the rest.
478	    lent_.clear();
479	    // Buffers the caller still holds stay alive through their own storage reference; dropping our
480	    // record here only releases the ones nobody kept.
481	    prune_owned();
482	}
